#!/usr/bin/env bash
# queuebash.sh - native Bash queue manager
# Source this from ~/.bashrc or ~/.bash_profile.
# priorities, hooks, exact-name grouping, bash completion, overdir/overfiles.

_queuebash_direct_execution_json_escape_early() {
    local s="${1:-}"
    s="${s//\\/\\\\}"
    s="${s//\"/\\\"}"
    s="${s//$'\n'/\\n}"
    s="${s//$'\r'/\\r}"
    s="${s//$'\t'/\\t}"
    printf '%s' "$s"
}
_queuebash_direct_execution_advice() {
    local json=0 arg script source_cmd bashrc_cmd
    for arg in "$@"; do case "$arg" in --json|-j) json=1 ;; esac; done
    script="${BASH_SOURCE[0]:-${0:-queuebash.sh}}"
    source_cmd="source $script"
    bashrc_cmd="printf '%s\n' 'source $script' >> ~/.bashrc"
    if [[ "$json" -eq 1 ]]; then
        printf '{"schema":"queuebash.direct_execution_advice.v1","status":"not_loaded","reason":"queuebash_must_be_sourced","message":"%s","source_command":"%s","bashrc_command":"%s","exit_code":2}\n' \
            "$(_queuebash_direct_execution_json_escape_early 'queuebash.sh was executed as a script. Source it into bash so the queue function and completions are loaded into the current shell.')" \
            "$(_queuebash_direct_execution_json_escape_early "$source_cmd")" \
            "$(_queuebash_direct_execution_json_escape_early "$bashrc_cmd")"
    else
        cat >&2 <<EOF_QUEUEBASH_DIRECT_EXECUTION
queuebash.sh was run as a script, so it cannot install the queue function into your current shell.

Source it into bash instead:
  source $script

To load it for future interactive shells:
  $bashrc_cmd

For automated callers that need machine-readable output:
  bash $script --json
EOF_QUEUEBASH_DIRECT_EXECUTION
    fi
}

if [[ "${BASH_SOURCE[0]:-}" == "${0:-}" ]]; then
    _queuebash_direct_execution_advice "$@"
    exit 2
fi

# Keep normal interactive guard if this file is used as a full .bashrc.
# Set QUEUEBASH_ALLOW_NONINTERACTIVE=1 before sourcing to use in scripts/tests.
if [[ -z "${QUEUEBASH_ALLOW_NONINTERACTIVE:-}" ]]; then
    case $- in
        *i*) ;;
        *) return 0 2>/dev/null || exit 0 ;;
    esac
fi

# Preserve a simple default prompt if caller has none.
: "${PS1:='\u@\h:\w> '}"

QUEUEBASH_VERSION="0.18.131"

# -------------------------------------------------------------------
# overdir / overfiles
# -------------------------------------------------------------------

_over_quote_cmd() {
    printf ' %q' "$@"
}
# QBTEST:BEGIN name=over-quote-cmd-basic function=_over_quote_cmd language=bash
# QBTEST:B64
# b3V0PSIkKF9vdmVyX3F1b3RlX2NtZCAiYWxwaGEgYmV0YSIgImdhbW1hIikiCltbICIkb3V0IiA9PSAqImFscGhhXCBiZXRhIiogXV0KW1sgIiRvdXQiID09ICoiZ2FtbWEiKiBdXQo=
# QBTEST:END

overdir() {
    local dryrun=0

    if [[ "$1" == "--help" || "$1" == "-h" || "$#" -eq 0 ]]; then
        _queue_resource_fetch_i18nl_command --name overdir-help.txt --lang "${QUEUEBASH_LANG:-${LANG:-lang_eng}}"
        return 0
    fi

    if [[ "$1" == "--dryrun" ]]; then
        dryrun=1
        shift
    fi

    if [[ "$#" -lt 2 ]]; then
        echo "Usage: overdir [--dryrun] <directory|dirspec...> <command... using {1}>"
        echo "Try: overdir --help"
        return 2
    fi

    local targets=()
    while [[ "$#" -gt 0 ]]; do
        local a="${1/#\~/$HOME}"

        if [[ -d "$a" ]]; then
            targets+=( "$a" )
            shift
            continue
        fi

        local matches=()
        local m
        while IFS= read -r m; do
            [[ -d "$m" ]] && matches+=( "$m" )
        done < <(compgen -G "$a")

        if [[ "${#matches[@]}" -gt 0 ]]; then
            targets+=( "${matches[@]}" )
            shift
            continue
        fi

        break
    done

    if [[ "${#targets[@]}" -eq 0 ]]; then
        echo "overdir: no directories matched" >&2
        return 1
    fi

    if [[ "$#" -eq 0 ]]; then
        echo "overdir: missing command" >&2
        return 2
    fi

    local cmd=( "$@" )
    local dir
    for dir in "${targets[@]}"; do
        echo "=== $dir ==="
        local args=()
        local x
        for x in "${cmd[@]}"; do
            args+=( "${x//\{1\}/$dir}" )
        done

        if [[ "$dryrun" -eq 1 ]]; then
            printf 'DRYRUN:'
            printf ' %q' "${args[@]}"
            printf '\n'
        else
            "${args[@]}"
        fi
    done
}

overfiles() {
    local dryrun=0

    if [[ "$1" == "--help" || "$1" == "-h" || "$#" -eq 0 ]]; then
        _queue_resource_fetch_i18nl_command --name overfiles-help.txt --lang "${QUEUEBASH_LANG:-${LANG:-lang_eng}}"
        return 0
    fi

    if [[ "$1" == "--dryrun" ]]; then
        dryrun=1
        shift
    fi

    if [[ "$#" -lt 2 ]]; then
        echo "Usage: overfiles [--dryrun] <file|filespec|directory...> <command... using {1}>"
        echo "Try: overfiles --help"
        return 2
    fi

    local targets=()
    while [[ "$#" -gt 0 ]]; do
        local a="${1/#\~/$HOME}"

        if [[ -e "$a" ]]; then
            targets+=( "$a" )
            shift
            continue
        fi

        local matches=()
        local m
        while IFS= read -r m; do
            [[ -e "$m" ]] && matches+=( "$m" )
        done < <(compgen -G "$a")

        if [[ "${#matches[@]}" -gt 0 ]]; then
            targets+=( "${matches[@]}" )
            shift
            continue
        fi

        break
    done

    if [[ "${#targets[@]}" -eq 0 ]]; then
        echo "overfiles: no files/directories matched" >&2
        return 1
    fi

    if [[ "$#" -eq 0 ]]; then
        echo "overfiles: missing command" >&2
        return 2
    fi

    local cmd=( "$@" )
    local files=()
    local t

    for t in "${targets[@]}"; do
        if [[ -d "$t" ]]; then
            local f
            while IFS= read -r -d '' f; do
                files+=( "$f" )
            done < <(find "$t" -mindepth 1 -maxdepth 1 -type f -print0)
        elif [[ -f "$t" ]]; then
            files+=( "$t" )
        fi
    done

    if [[ "${#files[@]}" -eq 0 ]]; then
        echo "overfiles: no files found" >&2
        return 1
    fi

    local file
    for file in "${files[@]}"; do
        echo "=== $file ==="
        local args=()
        local x
        for x in "${cmd[@]}"; do
            args+=( "${x//\{1\}/$file}" )
        done

        if [[ "$dryrun" -eq 1 ]]; then
            printf 'DRYRUN:'
            printf ' %q' "${args[@]}"
            printf '\n'
        else
            "${args[@]}"
        fi
    done
}

