_queue_job_pri() {
    local f="$1"
    local pri
    pri="$(grep '^PRIORITY=' "$f" 2>/dev/null | cut -d= -f2- | xargs printf '%s' 2>/dev/null)"
    pri="${pri:-10}"
    pri="${pri//[^0-9-]/}"
    [[ -z "$pri" ]] && pri=10
    printf '%s\n' "$pri"
}
# QBTEST:BEGIN name=job-pri function=_queue_job_pri language=bash
# QBTEST:B64
# 
# QBTEST:END


_queue_pending_bucket_key() {
    # Higher numeric PRIORITY dispatches first. Invert into fixed-width key so
    # shell glob order over pending/p*/ is priority order without worker-side sort.
    local pri="${1:-10}"
    [[ "$pri" =~ ^-?[0-9]+$ ]] || pri=10
    printf 'p%010d\n' $((1000000000 - pri))
}
# QBTEST:BEGIN name=pending-bucket-key function=_queue_pending_bucket_key language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_pending_path_for_priority() {
    local id="$1"
    local pri="${2:-10}"
    local root="${3:-$(_queue_root)}"
    printf '%s/pending/%s/%s.job\n' "$root" "$(_queue_pending_bucket_key "$pri")" "$id"
}
# QBTEST:BEGIN name=pending-path-for-priority function=_queue_pending_path_for_priority language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_pending_job_files() {
    local root="${1:-$(_queue_root)}"
    local d f id pri dest

    shopt -s nullglob

    # Compatibility normalisation: older queuebash versions stored jobs as
    # pending/<id>.job.  Move those legacy flat files into the same priority
    # buckets used by new submissions before producing the ordered list.  This
    # keeps legacy pending jobs in the correct priority order and prevents the
    # root pending directory from becoming a permanent mixed-format area.
    for f in "$root/pending"/*.job; do
        [[ -f "$f" ]] || continue
        id="$(basename "$f" .job)"
        pri="$(_queue_job_field_fast "$f" PRIORITY 2>/dev/null || echo 10)"
        [[ "$pri" =~ ^-?[0-9]+$ ]] || pri=10
        dest="$(_queue_pending_path_for_priority "$id" "$pri" "$root")"
        if [[ "$f" != "$dest" ]]; then
            mkdir -p -- "$(dirname "$dest")"
            mv -f -- "$f" "$dest" 2>/dev/null || true
        fi
    done

    for d in "$root/pending"/p*/; do
        [[ -d "$d" ]] || continue
        for f in "$d"*.job; do
            [[ -f "$f" ]] && printf '%s\n' "$f"
        done
        rmdir -- "$d" 2>/dev/null || true
    done

    shopt -u nullglob
}

_queue_job_pending_path_by_id() {
    local id="$1"
    local root="${2:-$(_queue_root)}"
    local f
    [[ -n "$id" ]] || return 1
    if [[ -f "$root/pending/$id.job" ]]; then
        printf '%s\n' "$root/pending/$id.job"
        return 0
    fi
    shopt -s nullglob
    for f in "$root/pending"/p*/"$id.job"; do
        if [[ -f "$f" ]]; then
            shopt -u nullglob
            printf '%s\n' "$f"
            return 0
        fi
    done
    shopt -u nullglob
    return 1
}
# QBTEST:BEGIN name=job-pending-path-by-id function=_queue_job_pending_path_by_id language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_is_pending_path() {
    local f="$1"
    local root="${2:-$(_queue_root)}"
    case "$f" in
        "$root/pending/"*.job|"$root/pending/"p*/*.job) return 0 ;;
        *) return 1 ;;
    esac
}
# QBTEST:BEGIN name=job-is-pending-path function=_queue_job_is_pending_path language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_state_for_job_path() {
    local f="$1"
    local root="${2:-$(_queue_root)}"
    local d
    case "$f" in
        "$root/pending/"*.job|"$root/pending/"p*/*.job) printf 'pending\n' ;;
        "$root/waiting/"*.job|"$root/waiting/"p*/*.job) printf 'waiting\n' ;;
        "$root/clearance/"*/*.job)
            d="$(dirname "$f")"
            basename "$d"
            ;;
        *) basename "$(dirname "$f")" ;;
    esac
}
# QBTEST:BEGIN name=state-for-job-path function=_queue_state_for_job_path language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_rebucket_pending_job() {
    local f="$1"
    local pri="${2:-10}"
    local root="${3:-$(_queue_root)}"
    local id dest olddir

    [[ -f "$f" ]] || return 1
    _queue_job_is_pending_path "$f" "$root" || return 0

    id="$(basename "$f" .job)"
    dest="$(_queue_pending_path_for_priority "$id" "$pri" "$root")"
    mkdir -p -- "$(dirname "$dest")"

    if [[ "$f" == "$dest" ]]; then
        return 0
    fi

    olddir="$(dirname "$f")"
    mv -f -- "$f" "$dest"

    case "$olddir" in
        "$root/pending"/p*) rmdir -- "$olddir" 2>/dev/null || true ;;
    esac
}

_queue_move_to_pending_bucket() {
    local src="$1"
    local id="${2:-}"
    local root="${3:-$(_queue_root)}"
    local pri dest olddir

    [[ -f "$src" ]] || return 1
    [[ -n "$id" ]] || id="$(basename "$src" .job)"

    pri="$(_queue_job_field_fast "$src" PRIORITY 2>/dev/null || echo 10)"
    [[ "$pri" =~ ^-?[0-9]+$ ]] || pri=10

    dest="$(_queue_pending_path_for_priority "$id" "$pri" "$root")"
    mkdir -p -- "$(dirname "$dest")"

    olddir="$(dirname "$src")"
    mv -f -- "$src" "$dest"

    case "$olddir" in
        "$root/pending"/p*) rmdir -- "$olddir" 2>/dev/null || true ;;
    esac
}

_queue_waiting_path_for_priority() {
    local id="$1"
    local pri="${2:-10}"
    local root="${3:-$(_queue_root)}"
    printf '%s/waiting/%s/%s.job\n' "$root" "$(_queue_pending_bucket_key "$pri")" "$id"
}

_queue_waiting_job_files() {
    local root="${1:-$(_queue_root)}"
    local d f id pri dest
    shopt -s nullglob
    for f in "$root/waiting"/*.job; do
        [[ -f "$f" ]] || continue
        id="$(basename "$f" .job)"
        pri="$(_queue_job_field_fast "$f" PRIORITY 2>/dev/null || echo 10)"
        [[ "$pri" =~ ^-?[0-9]+$ ]] || pri=10
        dest="$(_queue_waiting_path_for_priority "$id" "$pri" "$root")"
        if [[ "$f" != "$dest" ]]; then
            mkdir -p -- "$(dirname "$dest")"
            mv -f -- "$f" "$dest" 2>/dev/null || true
        fi
    done
    for d in "$root/waiting"/p*/; do
        [[ -d "$d" ]] || continue
        for f in "$d"*.job; do
            [[ -f "$f" ]] && printf '%s\n' "$f"
        done
        rmdir -- "$d" 2>/dev/null || true
    done
    shopt -u nullglob
}

_queue_job_waiting_path_by_id() {
    local id="$1"
    local root="${2:-$(_queue_root)}"
    local f
    [[ -n "$id" ]] || return 1
    if [[ -f "$root/waiting/$id.job" ]]; then
        printf '%s\n' "$root/waiting/$id.job"
        return 0
    fi
    shopt -s nullglob
    for f in "$root/waiting"/p*/"$id.job"; do
        if [[ -f "$f" ]]; then
            shopt -u nullglob
            printf '%s\n' "$f"
            return 0
        fi
    done
    shopt -u nullglob
    return 1
}

_queue_job_is_waiting_path() {
    local f="$1"
    local root="${2:-$(_queue_root)}"
    case "$f" in
        "$root/waiting/"*.job|"$root/waiting/"p*/*.job) return 0 ;;
        *) return 1 ;;
    esac
}

_queue_move_to_waiting_bucket() {
    local src="$1"
    local id="${2:-}"
    local root="${3:-$(_queue_root)}"
    local reason="${4:-preflight_wait}"
    local detail="${5:-waiting for queue conditions to pass}"
    local pri dest olddir now next

    [[ -f "$src" ]] || return 1
    [[ -n "$id" ]] || id="$(basename "$src" .job)"
    pri="$(_queue_job_field_fast "$src" PRIORITY 2>/dev/null || echo 10)"
    [[ "$pri" =~ ^-?[0-9]+$ ]] || pri=10
    now="$(_queue_now_iso)"
    next="$(date -d '+60 seconds' -Is 2>/dev/null || echo "$now")"
    {
        printf '\n# Waiting state recorded at %q\n' "$now"
        printf 'WAIT_REASON=%q\n' "$reason"
        printf 'WAIT_DETAIL=%q\n' "$detail"
        printf 'WAIT_LAST_PREFLIGHT=%q\n' "$now"
        printf 'WAIT_NEXT_CHECK=%q\n' "$next"
        printf 'WAIT_OPERATOR_ACTION=%q\n' "no_action_required"
        printf 'RUNNER_USED=%q\n' "none"
    } >> "$src"
    dest="$(_queue_waiting_path_for_priority "$id" "$pri" "$root")"
    mkdir -p -- "$(dirname "$dest")"
    olddir="$(dirname "$src")"
    mv -f -- "$src" "$dest"
    case "$olddir" in
        "$root/pending"/p*|"$root/waiting"/p*) rmdir -- "$olddir" 2>/dev/null || true ;;
    esac
}

_queue_job_field_fast() {
    local f="$1"
    local key="$2"
    local line val have=0
    [[ -f "$f" ]] || return 1
    while IFS= read -r line || [[ -n "$line" ]]; do
        case "$line" in
            "$key="*) val="${line#*=}"; have=1 ;;
        esac
    done < "$f"
    [[ "$have" -eq 1 ]] || return 1
    val="${val%\'}"; val="${val#\'}"
    val="${val%\"}"; val="${val#\"}"
    printf '%s\n' "$val"
}
# QBTEST:BEGIN name=job-field-fast function=_queue_job_field_fast language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_id_and_names_for_completion() {
    local root="$(_queue_root)"
    local state f id name
    for state in pending waiting running paused done failed pol_blocked policy_blocked interrupted cancelled deleted; do
        if [[ "$state" == "pending" || "$state" == "waiting" ]]; then
            local state_files_func="_queue_${state}_job_files"
            while IFS= read -r f; do
                [[ -e "$f" ]] || continue
                id="$(basename "$f" .job)"
                name="$(_queue_job_name "$f")"
                printf '%s\n' "$id"
                [[ -n "$name" ]] && printf '%s\n' "$name"
            done < <("$state_files_func" "$root")
            continue
        fi
        for f in "$root/$state"/*.job; do
            [[ -e "$f" ]] || continue
            id="$(basename "$f" .job)"
            name="$(_queue_job_name "$f")"
            printf '%s\n' "$id"
            [[ -n "$name" ]] && printf '%s\n' "$name"
        done
    done | sort -u
}

_queue_find_jobs() {
    # Exact QID wins; exact job name next; QID prefix last.
    # Searches live jobs, bucketed pending jobs, and clearance archives.
    # No job-name prefix matching.
    local needle="$1"
    local root="$(_queue_root)"
    local state f id name
    local exact_qid=()
    local exact_name=()
    local qid_prefix=()

    [[ -z "$needle" ]] && return 1

    for state in pending waiting running paused done failed pol_blocked policy_blocked interrupted cancelled deleted; do
        if [[ "$state" == "pending" || "$state" == "waiting" ]]; then
            local state_files_func="_queue_${state}_job_files"
            while IFS= read -r f; do
                [[ -e "$f" ]] || continue
                id="$(basename "$f" .job)"
                name="$(_queue_job_name "$f")"

                if [[ "$id" == "$needle" ]]; then
                    exact_qid+=( "$f" )
                elif [[ "$name" == "$needle" ]]; then
                    exact_name+=( "$f" )
                elif [[ "$id" == "$needle"* ]]; then
                    qid_prefix+=( "$f" )
                fi
            done < <("$state_files_func" "$root")
            continue
        fi
        for f in "$root/$state"/*.job; do
            [[ -e "$f" ]] || continue
            id="$(basename "$f" .job)"
            name="$(_queue_job_name "$f")"

            if [[ "$id" == "$needle" ]]; then
                exact_qid+=( "$f" )
            elif [[ "$name" == "$needle" ]]; then
                exact_name+=( "$f" )
            elif [[ "$id" == "$needle"* ]]; then
                qid_prefix+=( "$f" )
            fi
        done
    done

    shopt -s nullglob
    for f in "$root/clearance"/*/*.job; do
        [[ -e "$f" ]] || continue
        id="$(basename "$f" .job)"
        name="$(_queue_job_name "$f")"

        if [[ "$id" == "$needle" ]]; then
            exact_qid+=( "$f" )
        elif [[ "$name" == "$needle" ]]; then
            exact_name+=( "$f" )
        elif [[ "$id" == "$needle"* ]]; then
            qid_prefix+=( "$f" )
        fi
    done
    shopt -u nullglob

    if [[ "${#exact_qid[@]}" -gt 0 ]]; then
        printf '%s\n' "${exact_qid[@]}"
    elif [[ "${#exact_name[@]}" -gt 0 ]]; then
        printf '%s\n' "${exact_name[@]}"
    elif [[ "${#qid_prefix[@]}" -gt 0 ]]; then
        printf '%s\n' "${qid_prefix[@]}"
    else
        return 1
    fi
}
_queue_print_matches() {
    local root="$(_queue_root)"
    local f id state name
    for f in "$@"; do
        [[ -e "$f" ]] || continue
        id="$(basename "$f" .job)"
        state="$(_queue_state_for_job_path "$f" "$root")"
        name="$(_queue_job_name "$f")"
        printf "  %-24s %-10s %s\n" "$id" "$state" "$name" >&2
    done
}

_queue_exact_name_count() {
    local target="$1"
    shift
    local f name count=0
    for f in "$@"; do
        name="$(_queue_job_name "$f")"
        [[ "$name" == "$target" ]] && count=$((count + 1))
    done
    printf '%s\n' "$count"
}
# QBTEST:BEGIN name=exact-name-count function=_queue_exact_name_count language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_array_summary() {
    local file="$1"
    local varname="$2"

    [[ -f "$file" ]] || return 0

    (
        source "$file" 2>/dev/null || exit 0
        local -n arr="$varname" 2>/dev/null || exit 0
        local out=()
        local item

        for item in "${arr[@]}"; do
            [[ -n "$item" ]] && out+=( "$item" )
        done

        if [[ "${#out[@]}" -gt 0 ]]; then
            printf "%q" "${out[0]}"
            local i
            for ((i=1; i<${#out[@]}; i++)); do
                printf " %q" "${out[$i]}"
            done
        fi
    )
}

_queue_job_has_array() {
    local file="$1"
    local varname="$2"

    [[ -f "$file" ]] || return 1

    (
        source "$file" 2>/dev/null || exit 1
        local -n arr="$varname" 2>/dev/null || exit 1
        local item

        for item in "${arr[@]}"; do
            [[ -n "$item" ]] && exit 0
        done

        exit 1
    )
}
# QBTEST:BEGIN name=job-has-array function=_queue_job_has_array language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_set_job_array() {
    local file="$1"
    local varname="$2"
    shift 2

    local tmp
    tmp="$(mktemp)"

    if grep -q "^${varname}=" "$file"; then
        grep -v "^${varname}=" "$file" > "$tmp"
    else
        cat "$file" > "$tmp"
    fi

    {
        printf '%s=(' "$varname"
        printf ' %q' "$@"
        printf ' )\n'
    } >> "$tmp"

    mv "$tmp" "$file"
}

_queue_dep_token_done() {
    local token="$1"
    local root="$(_queue_root)"
    local f name id

    [[ -z "$token" ]] && return 1

    # Direct QID match.
    if [[ -f "$root/done/$token.job" ]]; then
        return 0
    fi

    # Exact job-name match in done/.
    for f in "$root/done"/*.job; do
        [[ -e "$f" ]] || continue
        name="$(_queue_job_name "$f")"
        [[ "$name" == "$token" ]] && return 0
    done

    return 1
}
# QBTEST:BEGIN name=dep-token-done function=_queue_dep_token_done language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_dep_token_failed_or_cancelled() {
    local token="$1"
    local root="$(_queue_root)"
    local state f name

    for state in failed interrupted cancelled deleted; do
        [[ -f "$root/$state/$token.job" ]] && return 0
        for f in "$root/$state"/*.job; do
            [[ -e "$f" ]] || continue
            name="$(_queue_job_name "$f")"
            [[ "$name" == "$token" ]] && return 0
        done
    done

    return 1
}
# QBTEST:BEGIN name=dep-token-failed-or-cancelled function=_queue_dep_token_failed_or_cancelled language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_dependency_tokens() {
    local f="$1"
    local value=""

    # Preferred path: source the job file, because DEPENDS_AFTER_SUCCESS is now
    # written as one shell-quoted string assignment.
    value="$(
        source "$f" 2>/dev/null
        printf '%s' "${DEPENDS_AFTER_SUCCESS:-}"
    )"

    if [[ -n "$value" ]]; then
        printf '%s\n' "$value"
        return 0
    fi

    # Compatibility fallback for early 0.6.0 job files that may contain an
    # unsafe unquoted line like: DEPENDS_AFTER_SUCCESS=foo bar
    grep '^DEPENDS_AFTER_SUCCESS=' "$f" 2>/dev/null | tail -1 | sed 's/^DEPENDS_AFTER_SUCCESS=//'
}
# QBTEST:BEGIN name=job-dependency-tokens function=_queue_job_dependency_tokens language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_dependencies_satisfied() {
    local f="$1"
    local deps dep
    deps="$(_queue_job_dependency_tokens "$f" || true)"
    [[ -z "$deps" ]] && return 0

    for dep in $deps; do
        _queue_dep_token_done "$dep" || return 1
    done

    return 0
}
# QBTEST:BEGIN name=job-dependencies-satisfied function=_queue_job_dependencies_satisfied language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_dependencies_status() {
    local f="$1"
    local deps dep
    deps="$(_queue_job_dependency_tokens "$f" || true)"
    [[ -z "$deps" ]] && { echo "none"; return 0; }

    for dep in $deps; do
        if _queue_dep_token_done "$dep"; then
            echo "$dep:done"
        elif _queue_dep_token_failed_or_cancelled "$dep"; then
            echo "$dep:blocked"
        else
            echo "$dep:waiting"
        fi
    done
}
# QBTEST:BEGIN name=job-dependencies-status function=_queue_job_dependencies_status language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_dependencies_blocked() {
    local f="$1"
    local deps dep
    deps="$(_queue_job_dependency_tokens "$f" || true)"
    [[ -z "$deps" ]] && return 1

    for dep in $deps; do
        _queue_dep_token_done "$dep" && continue
        _queue_dep_token_failed_or_cancelled "$dep" && return 0
    done

    return 1
}
# QBTEST:BEGIN name=job-dependencies-blocked function=_queue_job_dependencies_blocked language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_now_epoch() {
    printf '%(%s)T\n' -1 2>/dev/null || date +%s
}
# QBTEST:BEGIN name=now-epoch function=_queue_now_epoch language=bash
# QBTEST:B64
# ZT0iJChfcXVldWVfbm93X2Vwb2NoKSIKW1sgIiRlIiA9fiBeWzAtOV0rJCBdXQpbWyAiJGUiIC1ndCAxMDAwMDAwMDAwIF1d
# QBTEST:END

_queue_now_iso() {
    local ts
    if printf -v ts '%(%Y-%m-%dT%H:%M:%S%z)T' -1 2>/dev/null; then
        # Convert +0000 to +00:00 to stay close to `date -Is`.
        printf '%s:%s\n' "${ts:0:${#ts}-2}" "${ts: -2}"
    else
        date -Is 2>/dev/null || date
    fi
}
# QBTEST:BEGIN name=now-iso function=_queue_now_iso language=bash
# QBTEST:B64
# dD0iJChfcXVldWVfbm93X2lzbykiCltbIC1uICIkdCIgXV0KW1sgIiR0IiA9fiBeWzAtOV17NH0tWzAtOV17Mn0tWzAtOV17Mn1UWzAtOV17Mn06WzAtOV17Mn06WzAtOV17Mn0gXV0=
# QBTEST:END

_queue_parse_delay_seconds() {
    local spec="$1"
    local n unit total=0 rest

    [[ -z "$spec" ]] && return 1

    if [[ "$spec" =~ ^[0-9]+$ ]]; then
        printf '%s\n' "$spec"
        return 0
    fi

    rest="$spec"
    while [[ -n "$rest" ]]; do
        if [[ "$rest" =~ ^([0-9]+)([smhdw])(.*)$ ]]; then
            n="${BASH_REMATCH[1]}"
            unit="${BASH_REMATCH[2]}"
            rest="${BASH_REMATCH[3]}"
            case "$unit" in
                s) total=$((total + n)) ;;
                m) total=$((total + n * 60)) ;;
                h) total=$((total + n * 3600)) ;;
                d) total=$((total + n * 86400)) ;;
                w) total=$((total + n * 604800)) ;;
            esac
        else
            return 1
        fi
    done

    printf '%s\n' "$total"
}
# QBTEST:BEGIN name=parse-delay-seconds function=_queue_parse_delay_seconds language=bash
# QBTEST:B64
# W1sgIiQoX3F1ZXVlX3BhcnNlX2RlbGF5X3NlY29uZHMgMzApIiA9PSAiMzAiIF1dCltbICIkKF9xdWV1ZV9wYXJzZV9kZWxheV9zZWNvbmRzIDJtKSIgPT0gIjEyMCIgXV0KW1sgIiQoX3F1ZXVlX3BhcnNlX2RlbGF5X3NlY29uZHMgMCkiID09ICIwIiBdXQ==
# QBTEST:END

_queue_parse_at_epoch() {
    local spec="$1"
    local epoch today candidate

    [[ -z "$spec" ]] && return 1

    if [[ "$spec" =~ ^[0-9]+$ ]]; then
        printf '%s\n' "$spec"
        return 0
    fi

    if [[ "$spec" =~ ^[0-9]{1,2}:[0-9]{2}(:[0-9]{2})?$ ]]; then
        today="$(date +%Y-%m-%d)"
        candidate="$(date -d "$today $spec" +%s 2>/dev/null)" || return 1
        if (( candidate <= $(_queue_now_epoch) )); then
            candidate="$(date -d "tomorrow $spec" +%s 2>/dev/null)" || return 1
        fi
        printf '%s\n' "$candidate"
        return 0
    fi

    epoch="$(date -d "$spec" +%s 2>/dev/null)" || return 1
    printf '%s\n' "$epoch"
}
# QBTEST:BEGIN name=parse-at-epoch function=_queue_parse_at_epoch language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_not_before_epoch() {
    local f="$1"
    local nb rb
    nb="$(grep '^NOT_BEFORE_EPOCH=' "$f" 2>/dev/null | tail -1 | cut -d= -f2- | xargs printf '%s' 2>/dev/null)"
    rb="$(grep '^RETRY_NOT_BEFORE_EPOCH=' "$f" 2>/dev/null | tail -1 | cut -d= -f2- | xargs printf '%s' 2>/dev/null)"
    nb="${nb:-0}"
    rb="${rb:-0}"
    [[ "$nb" =~ ^[0-9]+$ ]] || nb=0
    [[ "$rb" =~ ^[0-9]+$ ]] || rb=0
    if (( rb > nb )); then
        printf '%s\n' "$rb"
    else
        printf '%s\n' "$nb"
    fi
}
# QBTEST:BEGIN name=job-not-before-epoch function=_queue_job_not_before_epoch language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_schedule_due() {
    local f="$1"
    local due
    due="$(_queue_job_not_before_epoch "$f")"
    (( due <= $(_queue_now_epoch) ))
}
# QBTEST:BEGIN name=job-schedule-due function=_queue_job_schedule_due language=bash
# QBTEST:B64
# 
# QBTEST:END

_queue_job_schedule_status() {
    local f="$1"
    local due now remain when
    due="$(_queue_job_not_before_epoch "$f")"
    now="$(_queue_now_epoch)"
    when="$(date -d "@$due" -Is 2>/dev/null || echo "$due")"
    if (( due <= now )); then
        echo "due"
    else
        remain=$((due - now))
        echo "waiting ${remain}s until $when"
    fi
}
