_queue_class_file() {
    local class="$1"
    local root="$(_queue_root)"
    local exact="$root/classes/$class.env"
    local f base

    if [[ -f "$exact" ]]; then
        printf '%s\n' "$exact"
        return 0
    fi

    shopt -s nullglob
    for f in "$root/classes"/*.env; do
        base="$(basename "$f" .env)"
        if [[ "${base,,}" == "${class,,}" ]]; then
            printf '%s\n' "$f"
            shopt -u nullglob
            return 0
        fi
    done
    shopt -u nullglob

    printf '%s\n' "$exact"
}
