_queue_asset_facility_is_published() {
    local family="$1"
    local check="$2"
    local facility="${family}:${check}"

    if declare -F queue_asset_facilities >/dev/null 2>&1; then
        queue_asset_facilities | awk '{print $1}' | grep -Fxq "$facility"
        return "$?"
    fi

    return 1
}
