_queue_exception_job_id_from_current_context() {
    if [[ -n "${JOB_ID:-}" ]]; then
        printf '%s\n' "$JOB_ID"
        return 0
    fi
    if [[ -n "${QUEUEBASH_CLASS_JOB_ID:-}" ]]; then
        printf '%s\n' "$QUEUEBASH_CLASS_JOB_ID"
        return 0
    fi
    return 1
}

_queue_exception_normalize_key() {
    local key="${1:-}"
    key="${key//[^A-Za-z0-9_:-]/_}"
    printf '%s\n' "$key"
}
