_queue_home_for_user() {
    local user="${1:-}"
    [[ -n "$user" ]] || return 1
    getent passwd "$user" 2>/dev/null | awk -F: '{print $6; exit}'
}

_queue_root_for_user() {
    local user="${1:-}"
    local home
    home="$(_queue_home_for_user "$user")" || return 1
    [[ -n "$home" ]] || return 1
    printf '%s/.queuebash\n' "$home"
}
