# QBTEST:B64
# 
# QBTEST:END

_queue_security_seccomp_rank() {
    case "${1,,}" in
        off|none) echo 0 ;;
        docker-default|queue-default) echo 1 ;;
        strict) echo 2 ;;
        *) echo 0 ;;
    esac
}
# QBTEST:BEGIN name=security-seccomp-rank-order function=_queue_security_seccomp_rank language=bash
