_queue_authorisation_signer_private_key_file() {
    local signer="${1:-}" name="${2:-}"
    [[ -n "$name" ]] || name="$signer"
    _queue_authorisation_key_name_ok "$name" || return 1
    printf '%s/private/%s.ed25519.pem\n' "$(_queue_authorisation_signer_key_root "$signer")" "$name"
