_queue_authorisation_public_key_file() {
    local name="${1:-}"
    _queue_authorisation_key_name_ok "$name" || return 1
    printf '%s/public/%s.ed25519.pub.pem\n' "$(_queue_authorisation_key_root)" "$name"
