# QBTEST:END

_queue_policy_shared_root() {
    printf '%s\n' "${QUEUEBASH_SHARED_POLICY_ROOT:-/etc/queuebash/policies.d}"
}
# QBTEST:BEGIN name=policy-shared-root-override function=_queue_policy_shared_root language=bash
