_queue_cron_system_dir() { printf '%s\n' "${QUEUEBASH_CRON_SYSTEM_DIR:-/etc/bashqueues_cron.d}"; }
# QBTEST:BEGIN name=cron-system-dir-env-default function=_queue_cron_system_dir language=bash
