_queue_ai_audit_log_path() {
    if [[ -n "${QUEUEBASH_AI_AUDIT_LOG:-}" ]]; then
        printf '%s\n' "$QUEUEBASH_AI_AUDIT_LOG"
        return 0
    fi
    local root
    root="$(_queue_root 2>/dev/null || true)"
    [[ -n "$root" ]] || root="${HOME:-/tmp}/.queuebash"
    printf '%s/logs/ai-advisory.audit.jsonl\n' "$root"
}
