_queue_ai_redact_question() {
    local q="$1"
    q="${q//$'\n'/ }"
    q="${q//$'\r'/ }"
    q="${q//$'\t'/ }"
    if [[ "${#q}" -gt 180 ]]; then
        q="${q:0:180}..."
    fi
    printf '%s' "$q"
}
