    local provider="${6:-${QUEUEBASH_ACL_PROVIDER:-contract}}"
    local evidence_json="${7:-[]}"
    local fail_closed="${8:-true}"
    local contract_only="${9:-false}"
    local ttl_seconds="${10:-0}"
    local cache_policy="${11:-no-store}"
    printf '{'
